// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    // A minimal helper that simulates a callee which always succeeds the low-level call
    // (since fuzzed raw addresses are EOAs with no code and .call would succeed but do nothing,
    // we provide a contract that implements the expected transferFrom signature and returns true)
    contract GoodCallee {
        // match selector: transferFrom(address,address,uint256)
        function transferFrom(address, address, uint) external pure returns (bool) {
            return true;
        }
    }

    function setUp() public { c = new C(); }

    // Fuzz parameters: an address 'from', address helper is deployed (not fuzzed),
    // dynamic arrays for recipients and amounts are fuzzed.
    function testFuzz_property(address from, address dummy, address[] memory tos, uint[] memory vals) public {
        // Keep arrays lengths reasonable but allow empty to be filtered by require in transfer
        // Ensure arrays have same length and not overly large to avoid gas issues
        // Allow fuzzer to pick lengths, but constrain to <= 10 to keep test practical
        uint maxLen = 10;
        if (tos.length != vals.length) return; // skip mismatched lengths (admissible domain requires equal lengths)
        if (tos.length > maxLen) return; // keep domain wide but practical

        // deploy adversarial counterpart that will respond to transferFrom and succeed
        GoodCallee helper = new GoodCallee();

        // Now call c.transfer with the helper address as caddress
        // We need to observe the returned boolean. Use try/catch to capture return without reverting.
        bool ok;
        try c.transfer(from, address(helper), tos, vals) returns (bool ret) {
            ok = ret;
        } catch {
            // If it reverts, consider it not-ok (but reference reverts on empty tos via require)
            ok = false;
        }

        // General rule: when transfer does not revert, reference returns true for all inputs.
        // We assert that the call returned true. This holds for the reference implementation for all admissible inputs,
        // but the mutant (which returns false at the end) will cause this assertion to fail for some inputs
        // where the function completes (e.g., tos.length > 0 and helper returns true for each internal call).
        assertTrue(ok);
    }
}

