// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // We fuzz the 'from' address and an array length and single recipient/value via encoded calldata.
    // The deciding values are: an address 'fromAddr' and uint8 len (length of arrays).
    function testFuzz_property(address fromAddr, uint8 len) public {
        // keep len in a reasonable wide bound but allow zero to be excluded because function requires >0
        uint256 l = bound(uint256(len), 0, 8);
        vm.assume(l > 0); // admissible domain: _tos.length > 0

        // deploy a simple success callee that will accept transferFrom calls and return true
        SuccessCallee sc = new SuccessCallee();

        // prepare arrays of addresses and values of length l
        address[] memory tos = new address[](l);
        uint[] memory vals = new uint[](l);
        for (uint i = 0; i < l; i++) {
            tos[i] = address(sc);
            vals[i] = 1 + i; // arbitrary nonzero values
        }

        // Call transfer and capture return via try/catch to observe non-revert completion and return value
        bool ok;
        try c.transfer(fromAddr, address(sc), tos, vals) returns (bool ret) {
            // The reference implementation returns true for any non-reverting invocation
            ok = ret; // should be true for reference; mutant would return false
        } catch {
            // any revert would make the call not complete; we restrict to non-reverting domain by using SuccessCallee
            ok = false;
        }

        // Exactly one assertion: the reference C satisfies that for these admissible inputs (non-reverting callee)
        // transfer(...) returns true. The mutant (which returns false) will break this for some inputs.
        assertTrue(ok);
    }
}

// Adversarial helper that always successfully handles transferFrom and returns true
contract SuccessCallee {
    // emulate ERC20-like transferFrom signature
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }

    // fallback to accept any calldata as long as selector matches or not; return true for matching selector
    fallback() external payable returns (bytes memory) {
        // If called with the selector of transferFrom(address,address,uint256), return true-encoded
        bytes4 id = bytes4(keccak256("transferFrom(address,address,uint256)"));
        if (msg.data.length >= 4) {
            bytes4 sel;
            assembly { sel := calldataload(0) }
            if (sel == id) {
                // return abi.encode(true)
                bytes memory out = abi.encode(true);
                return out;
            }
        }
        return "";
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    // A minimal callee that will accept any call and return success so that transfer completes.
    // This ensures calls inside transfer succeed and do not revert, letting the function reach its return.
    Callee good;

    function setUp() public { 
        c = new C();
        good = new Callee();
    }

    // Fuzz the from address and arrays length and values. The fuzzer will provide addresses and amounts.
    // We must ensure _tos length > 0 (required by require) and arrays lengths match.
    function testFuzz_property(address from, address a0, address a1, uint256 v0, uint256 v1, uint8 len) public {
        // keep length small but >=1 to satisfy require(_tos.length > 0)
        uint256 l = uint256(len) % 2 + 1; // l in {1,2}

        address[] memory tos = new address[](l);
        uint[] memory vals = new uint[](l);

        tos[0] = address(good);
        vals[0] = v0;
        if(l == 2){
            // use provided second address and value
            tos[1] = a1;
            vals[1] = v1;
        }

        // Call transfer and observe whether it returns true (reference does) by catching the returned boolean via try/catch
        bool ok;
        try c.transfer(from, address(good), tos, vals) returns (bool ret) {
            // record whether return value is true
            ok = ret;
        } catch {
            // if it reverts, mark false
            ok = false;
        }

        // The reference contract always returns true (when it does not revert). This assert reads c's behavior
        // and will fail for the mutant which returns !true (false) for completing calls.
        assertTrue(ok);
    }
}

// Minimal callee that always returns true for the called selector
contract Callee {
    // Accept any calldata and return true (as bytes) to mimic successful ERC20-like transferFrom
    fallback() external payable returns (bytes memory) {
        // return a single bool true encoded
        bytes memory ret = abi.encode(true);
        return ret;
    }
}
